import { createClient, type SupabaseClient } from '@supabase/supabase-js';
import { AppState, type AppStateStatus, Platform } from 'react-native';

import { supabaseConfig } from './config.supabase';
import type { Database } from './database.supabase';
import { authSessionStorage } from './session-storage.supabase';
import { installWebCrypto } from './web-crypto.supabase';

/** The client, typed with the cloud tables (`database.supabase.ts`, generated by `bun run db:types`). */
export type CoinrootSupabase = SupabaseClient<Database>;

let client: CoinrootSupabase | null | undefined;

/**
 * The one Supabase client, created on first use. `null` when this build has no Supabase
 * settings (the app then works fully offline, without sign-in).
 *
 * Email links (confirm sign-up, reset password) use the PKCE flow: the link opens
 * `coinroot://auth-callback?code=…&sb_flow_id=…`, and the `auth-callback` route redeems the
 * code with the secret this phone stored when it asked for the email. A link this phone
 * didn't ask for (e.g. one with someone else's tokens) can't sign it in.
 */
export function getSupabase(): CoinrootSupabase | null {
  if (client !== undefined) return client;
  if (!supabaseConfig) {
    client = null;
    return client;
  }

  const native = Platform.OS !== 'web';
  if (native) installWebCrypto();
  const supabase = createClient<Database>(supabaseConfig.url, supabaseConfig.publishableKey, {
    auth: {
      // Web uses the browser's localStorage (Supabase's default); nothing to keep on the server render.
      storage: native ? authSessionStorage : undefined,
      persistSession: native || typeof window !== 'undefined',
      autoRefreshToken: true,
      detectSessionInUrl: false,
      // Email links carry a one-time code that only works with the secret this phone stored
      // when it asked for the email, so a link from someone else can't sign this phone in.
      flowType: 'pkce',
    },
  });

  if (native) {
    // React Native has no tab visibility events: refresh tokens only while the app is open.
    const sync = (state: AppStateStatus | null | undefined) => {
      if (state === 'active' || state == null) void supabase.auth.startAutoRefresh();
      else void supabase.auth.stopAutoRefresh();
    };
    AppState.addEventListener('change', sync);
    // `currentState` can be unknown this early: the app is in the foreground while it starts.
    sync(AppState.currentState as AppStateStatus | null);
  }

  client = supabase;
  return client;
}
